/**
 * The workspace split's data movement: one project of a legacy multi-project
 * account becomes its own workspace (a fresh account) in ONE transaction.
 * Workspaces design.md §2 "Transfer engine fixes"; the runner, ledger and lease
 * live in `workspaces/split/`.
 *
 * What the split does, in the caller's transaction:
 *
 *   1. Creates the target account `toAccountId` (pre-generated by the runner)
 *      named after the project, with the source's security settings and
 *      branding. It starts with no billing rows: the runner initializes Free
 *      with 0 credits after commit. Money (wallet, Stripe, contracts) stays
 *      with the source, which keeps the most recently opened project.
 *   2. Copies the directory, so every access path to the project survives:
 *      every membership (owners and admins included), every group with its
 *      members, every custom role with its permissions, and every
 *      account-scope grant (users, groups, the project's service accounts,
 *      and pending invitees whose invite is split here).
 *   3. Copies the account-wide secrets (`project_id IS NULL`) re-encrypted
 *      with the target key, with their member grants, and rewrites the moved
 *      sessions' provider pools to the copies.
 *   4. Copies GitHub installations, GitHub user tokens (re-encrypted) and
 *      legacy Claude logins (re-encrypted).
 *   5. Splits pending invites: the moved project's `bootstrap_grants` entries
 *      leave the source invite and form a new invite in the target.
 *   6. Moves the project through `moveProjectInTransaction` in split mode:
 *      group, custom-role and pending grants are remapped to the copies.
 *
 * Every copied id is returned ({@link SplitCopiedIds}); the runner stores it
 * in `workspace_split_runs.copied_ids` and {@link reverseProjectSplit} deletes
 * exactly those rows.
 *
 * Stays with the source (the keeper): OAuth clients and tokens, API keys,
 * account tokens with no project, Capture, tunnels, ledgers, audit history.
 */
import { randomUUID } from 'node:crypto';
import { sql } from 'drizzle-orm';
import { decryptAccountSecret, encryptAccountSecret } from '../../secrets/account-resource';
import { pendingPrincipalId } from '../../iam/actor';
import { logger } from '../../lib/logger';
import { moveProjectInTransaction, type TransferTx } from './project-transfer';

/** Every row the split created in the target, by kind. JSON-safe. */
export interface SplitCopiedIds {
  account: string;
  /** user ids with a copied membership in the target. */
  memberships: string[];
  /** source group id → copy. */
  groups: Record<string, string>;
  /** source custom role id → copy. */
  roles: Record<string, string>;
  /** assignment ids of the copied account-scope grants. */
  accountAssignments: string[];
  /** source account-wide secret id → copy. */
  secrets: Record<string, string>;
  /** source secrets left behind because this server cannot decrypt them. */
  undecryptableSecrets: string[];
  /** provider pools rewritten to the copies, with the ids they held before. */
  pools: Array<{ sessionId: string; providerId: string; before: string[] }>;
  githubInstallations: string[];
  githubUserTokens: string[];
  /** user ids with a copied legacy Claude login. */
  claudeLogins: string[];
  /** invite created in the target, the source invite it came from, and the entries it took. */
  invites: Array<{ inviteId: string; sourceInviteId: string; moved: unknown[] }>;
}

export type ProjectSplitErrorCode = 'not_legacy' | 'project_missing' | 'reverse_refused';

export class ProjectSplitError extends Error {
  constructor(readonly code: ProjectSplitErrorCode, message: string) {
    super(message);
    this.name = 'ProjectSplitError';
  }
}

type Row = Record<string, unknown>;
const ids = (rows: Row[], key: string) => rows.map((row) => String(row[key]));
const jsonMap = (map: Readonly<Record<string, string>>) => JSON.stringify(map);
const invert = (map: Readonly<Record<string, string>>) => Object.fromEntries(Object.entries(map).map(([k, v]) => [v, k]));

function reseal(fromAccountId: string, toAccountId: string, envelope: string | null): string | null {
  if (envelope === null) return null;
  return encryptAccountSecret(toAccountId, decryptAccountSecret(fromAccountId, envelope));
}

/**
 * Who reaches the project through a grant, per principal (`type:id`): the
 * project-scope grants on it plus the account-scope grants the split copies.
 * Pending invitees are left out (their grants move with their invite). The
 * split stores this before the move; invariant I7 compares it after.
 */
export async function projectGrantCounts(tx: TransferTx, accountId: string, projectId: string, groupMap: Readonly<Record<string, string>> = {}): Promise<Record<string, number>> {
  const rows = await tx.execute<{ principal_type: string; principal_id: string; n: number }>(sql`
    SELECT ra.principal_type, ra.principal_id::text AS principal_id, count(*)::int AS n
      FROM kortix.role_assignments ra
     WHERE ra.account_id = ${accountId}
       AND (ra.expires_at IS NULL OR ra.expires_at > now())
       AND ra.principal_type IN ('user', 'group', 'service_account', 'project')
       AND ((ra.scope_type = 'project' AND ra.scope_id = ${projectId})
         OR (ra.scope_type = 'account' AND (ra.principal_type <> 'service_account' OR ra.principal_id IN (
               SELECT service_account_id FROM kortix.service_accounts WHERE project_id = ${projectId}))))
     GROUP BY 1, 2`);
  const counts: Record<string, number> = {};
  for (const row of rows) {
    const id = row.principal_type === 'group' ? (groupMap[row.principal_id] ?? row.principal_id) : row.principal_id;
    counts[`${row.principal_type}:${id}`] = (counts[`${row.principal_type}:${id}`] ?? 0) + row.n;
  }
  return counts;
}

/** Steps 1–2: the target account and its copy of the source directory. */
async function copyDirectory(tx: TransferTx, projectId: string, fromAccountId: string, toAccountId: string, invitedEmails: string[], out: SplitCopiedIds): Promise<void> {
  await tx.execute(sql`
    INSERT INTO kortix.accounts (account_id, name, setup_complete_at, setup_wizard_step, mfa_required,
      session_max_lifetime_minutes, session_idle_timeout_minutes, pat_max_lifetime_days, pat_require_expiry,
      pat_idle_revoke_days, admins_see_all_sessions, automations_paused_at, automations_paused_by, branding)
    SELECT ${toAccountId}::uuid, p.name, a.setup_complete_at, a.setup_wizard_step, a.mfa_required,
      a.session_max_lifetime_minutes, a.session_idle_timeout_minutes, a.pat_max_lifetime_days, a.pat_require_expiry,
      a.pat_idle_revoke_days, a.admins_see_all_sessions, a.automations_paused_at, a.automations_paused_by, a.branding
      FROM kortix.accounts a JOIN kortix.projects p ON p.account_id = a.account_id
     WHERE a.account_id = ${fromAccountId} AND p.project_id = ${projectId}`);

  // SCIM external ids are per identity-provider connection, which stays with
  // the source: the copy carries none.
  const members = await tx.execute<{ user_id: string }>(sql`
    INSERT INTO kortix.account_memberships (user_id, account_id, is_super_admin, joined_at)
    SELECT user_id, ${toAccountId}::uuid, is_super_admin, joined_at FROM kortix.account_memberships
     WHERE account_id = ${fromAccountId}
    RETURNING user_id::text`);
  out.memberships = ids(members, 'user_id');

  const groups = await tx.execute<{ group_id: string }>(sql`
    SELECT group_id::text FROM kortix.account_groups WHERE account_id = ${fromAccountId} ORDER BY group_id`);
  for (const { group_id } of groups) out.groups[group_id] = randomUUID();
  if (groups.length) {
    await tx.execute(sql`
      INSERT INTO kortix.account_groups (group_id, account_id, name, description, source, external_id, created_by, created_at, updated_at)
      SELECT (${jsonMap(out.groups)}::jsonb ->> g.group_id::text)::uuid, ${toAccountId}::uuid, g.name, g.description,
             g.source, g.external_id, g.created_by, g.created_at, g.updated_at
        FROM kortix.account_groups g WHERE g.account_id = ${fromAccountId}`);
    await tx.execute(sql`
      INSERT INTO kortix.group_members (group_id, user_id, added_by, added_at)
      SELECT (${jsonMap(out.groups)}::jsonb ->> gm.group_id::text)::uuid, gm.user_id, gm.added_by, gm.added_at
        FROM kortix.group_members gm JOIN kortix.account_groups g ON g.group_id = gm.group_id
       WHERE g.account_id = ${fromAccountId}`);
  }

  const roles = await tx.execute<{ role_id: string }>(sql`
    SELECT role_id::text FROM kortix.roles WHERE account_id = ${fromAccountId} ORDER BY role_id`);
  for (const { role_id } of roles) out.roles[role_id] = randomUUID();
  if (roles.length) {
    await tx.execute(sql`
      INSERT INTO kortix.roles (role_id, account_id, key, name, description, scope_type, is_system, created_by, created_at, updated_at)
      SELECT (${jsonMap(out.roles)}::jsonb ->> r.role_id::text)::uuid, ${toAccountId}::uuid, r.key, r.name, r.description,
             r.scope_type, r.is_system, r.created_by, r.created_at, r.updated_at
        FROM kortix.roles r WHERE r.account_id = ${fromAccountId}`);
    await tx.execute(sql`
      INSERT INTO kortix.role_permissions (role_id, action)
      SELECT (${jsonMap(out.roles)}::jsonb ->> rp.role_id::text)::uuid, rp.action
        FROM kortix.role_permissions rp JOIN kortix.roles r ON r.role_id = rp.role_id
       WHERE r.account_id = ${fromAccountId}`);
  }

  const pendingIds = invitedEmails.map(pendingPrincipalId);
  const assignments = await tx.execute<{ assignment_id: string }>(sql`
    INSERT INTO kortix.role_assignments (account_id, principal_type, principal_id, role_id, scope_type, scope_id,
      object_type, object_id, expires_at, granted_by, source, created_at, updated_at)
    SELECT ${toAccountId}::uuid, ra.principal_type,
           CASE WHEN ra.principal_type = 'group' THEN (${jsonMap(out.groups)}::jsonb ->> ra.principal_id::text)::uuid ELSE ra.principal_id END,
           COALESCE((${jsonMap(out.roles)}::jsonb ->> ra.role_id::text)::uuid, ra.role_id),
           'account', NULL, ra.object_type, ra.object_id, ra.expires_at, ra.granted_by, ra.source, ra.created_at, now()
      FROM kortix.role_assignments ra
     WHERE ra.account_id = ${fromAccountId} AND ra.scope_type = 'account'
       AND (ra.principal_type IN ('user', 'group')
         OR (ra.principal_type = 'service_account' AND ra.principal_id IN (
               SELECT service_account_id FROM kortix.service_accounts WHERE project_id = ${projectId}))
         OR (ra.principal_type = 'pending' AND ra.principal_id::text IN (SELECT jsonb_array_elements_text(${JSON.stringify(pendingIds)}::jsonb))))
    RETURNING assignment_id::text`);
  out.accountAssignments = ids(assignments, 'assignment_id');
}

/** Step 3: account-wide secrets, their grants, and the moved sessions' pools. */
async function copyAccountSecrets(tx: TransferTx, projectId: string, fromAccountId: string, toAccountId: string, out: SplitCopiedIds): Promise<void> {
  const secrets = await tx.execute<Row & { secret_id: string; value_enc: string }>(sql`
    SELECT * FROM kortix.account_secret_resources
     WHERE account_id = ${fromAccountId} AND project_id IS NULL ORDER BY secret_id FOR SHARE`);
  for (const secret of secrets) {
    let valueEnc: string;
    try {
      valueEnc = encryptAccountSecret(toAccountId, decryptAccountSecret(fromAccountId, secret.value_enc));
    } catch {
      // Unusable in the source too; a member reconnects it in the new workspace.
      out.undecryptableSecrets.push(secret.secret_id);
      continue;
    }
    const copyId = randomUUID();
    out.secrets[secret.secret_id] = copyId;
    await tx.execute(sql`
      INSERT INTO kortix.account_secret_resources (secret_id, account_id, label, project_id, access_mode, provider_id, name,
        value_enc, consumer, strategy, active, cooldown_until, cooldown_probe_at, needs_reauth_at, usage, usage_checked_at,
        provider_account, created_by, created_at, updated_at)
      SELECT ${copyId}::uuid, ${toAccountId}::uuid, label, NULL, access_mode, provider_id, name, ${valueEnc}, consumer, strategy,
             active, cooldown_until, cooldown_probe_at, needs_reauth_at, usage, usage_checked_at, provider_account,
             created_by, created_at, updated_at
        FROM kortix.account_secret_resources WHERE secret_id = ${secret.secret_id}`);
  }
  if (!Object.keys(out.secrets).length) return;
  await tx.execute(sql`
    INSERT INTO kortix.account_secret_grants (secret_id, account_id, user_id, granted_by, created_at)
    SELECT (${jsonMap(out.secrets)}::jsonb ->> g.secret_id::text)::uuid, ${toAccountId}::uuid, g.user_id, g.granted_by, g.created_at
      FROM kortix.account_secret_grants g
     WHERE g.account_id = ${fromAccountId} AND (${jsonMap(out.secrets)}::jsonb ? g.secret_id::text)`);
  out.pools = await rewriteProjectPools(tx, projectId, out.secrets);
}

/** Replace pooled secret ids by `map` in the project's sessions; returns the rows changed with their old ids. */
async function rewriteProjectPools(tx: TransferTx, projectId: string, map: Readonly<Record<string, string>>): Promise<SplitCopiedIds['pools']> {
  const pools = await tx.execute<{ session_id: string; provider_id: string; secret_ids: string[] }>(sql`
    SELECT pp.session_id, pp.provider_id, pp.secret_ids FROM kortix.session_provider_secret_pools pp
      JOIN kortix.project_sessions s ON s.session_id = pp.session_id
     WHERE s.project_id = ${projectId} FOR UPDATE OF pp`);
  const changed: SplitCopiedIds['pools'] = [];
  for (const pool of pools) {
    const before = Array.isArray(pool.secret_ids) ? pool.secret_ids : [];
    if (!before.some((id) => id in map)) continue;
    const after = before.map((id) => map[id] ?? id);
    await tx.execute(sql`UPDATE kortix.session_provider_secret_pools SET secret_ids = ${JSON.stringify(after)}::jsonb, updated_at = now()
      WHERE session_id = ${pool.session_id} AND provider_id = ${pool.provider_id}`);
    changed.push({ sessionId: pool.session_id, providerId: pool.provider_id, before });
  }
  return changed;
}

/** Step 4: GitHub installations, GitHub user tokens, legacy Claude logins. */
async function copyIntegrations(tx: TransferTx, fromAccountId: string, toAccountId: string, out: SplitCopiedIds): Promise<void> {
  const installations = await tx.execute<{ installation_row_id: string }>(sql`
    INSERT INTO kortix.account_github_installations (account_id, installation_id, owner_login, owner_type,
      repository_selection, permissions, metadata, created_at, updated_at)
    SELECT ${toAccountId}::uuid, installation_id, owner_login, owner_type, repository_selection, permissions, metadata, created_at, updated_at
      FROM kortix.account_github_installations WHERE account_id = ${fromAccountId}
    RETURNING installation_row_id::text`);
  out.githubInstallations = ids(installations, 'installation_row_id');

  const tokens = await tx.execute<Row & { token_row_id: string; value_enc: string; refresh_value_enc: string | null }>(sql`
    SELECT * FROM kortix.account_github_user_tokens WHERE account_id = ${fromAccountId} ORDER BY token_row_id FOR SHARE`);
  for (const token of tokens) {
    let sealed: { value: string; refresh: string | null };
    try {
      sealed = { value: reseal(fromAccountId, toAccountId, token.value_enc)!, refresh: reseal(fromAccountId, toAccountId, token.refresh_value_enc) };
    } catch {
      continue; // unreadable in the source too: the member reconnects GitHub
    }
    const [row] = await tx.execute<{ token_row_id: string }>(sql`
      INSERT INTO kortix.account_github_user_tokens (account_id, user_id, github_login, value_enc, refresh_value_enc, expires_at, created_at, updated_at)
      SELECT ${toAccountId}::uuid, user_id, github_login, ${sealed.value}, ${sealed.refresh}, expires_at, created_at, updated_at
        FROM kortix.account_github_user_tokens WHERE token_row_id = ${token.token_row_id}
      RETURNING token_row_id::text`);
    if (row) out.githubUserTokens.push(row.token_row_id);
  }

  const logins = await tx.execute<{ user_id: string; value_enc: string }>(sql`
    SELECT user_id::text, value_enc FROM kortix.claude_subscription_logins WHERE account_id = ${fromAccountId} FOR SHARE`);
  for (const login of logins) {
    let valueEnc: string;
    try {
      valueEnc = reseal(fromAccountId, toAccountId, login.value_enc)!;
    } catch {
      continue;
    }
    await tx.execute(sql`
      INSERT INTO kortix.claude_subscription_logins (account_id, user_id, value_enc, source, created_at, updated_at)
      SELECT ${toAccountId}::uuid, user_id, ${valueEnc}, source, created_at, updated_at
        FROM kortix.claude_subscription_logins WHERE account_id = ${fromAccountId} AND user_id = ${login.user_id}`);
    out.claudeLogins.push(login.user_id);
  }
}

type PendingInvite = { invite_id: string; email: string; bootstrap_grants: unknown[] };

const grantsProject = (entry: unknown, projectId: string) =>
  typeof entry === 'object' && entry !== null && (entry as { project_id?: unknown }).project_id === projectId;

async function pendingInvitesForProject(tx: TransferTx, projectId: string, fromAccountId: string): Promise<PendingInvite[]> {
  return tx.execute<PendingInvite>(sql`
    SELECT invite_id::text, email, bootstrap_grants FROM kortix.account_invitations
     WHERE account_id = ${fromAccountId} AND accepted_at IS NULL AND expires_at > now()
       AND bootstrap_grants @> ${JSON.stringify([{ project_id: projectId }])}::jsonb
     ORDER BY invite_id FOR UPDATE`);
}

/** Step 5: the moved project's invite entries leave the source invite for a new one in the target. */
async function splitInvites(tx: TransferTx, projectId: string, fromAccountId: string, toAccountId: string, invites: PendingInvite[], out: SplitCopiedIds): Promise<void> {
  for (const invite of invites) {
    const entries = Array.isArray(invite.bootstrap_grants) ? invite.bootstrap_grants : [];
    const moved = entries.filter((entry) => grantsProject(entry, projectId));
    const kept = entries.filter((entry) => !grantsProject(entry, projectId));
    // A SCIM-parked group entry rides along with the copy of its group.
    const groupEntries = entries.flatMap((entry) => {
      const groupId = typeof entry === 'object' && entry !== null ? (entry as { group_id?: unknown }).group_id : undefined;
      return typeof groupId === 'string' && out.groups[groupId] ? [{ group_id: out.groups[groupId] }] : [];
    });
    const [created] = await tx.execute<{ invite_id: string }>(sql`
      INSERT INTO kortix.account_invitations (account_id, email, invited_by, initial_role, bootstrap_grants, created_at, expires_at)
      SELECT ${toAccountId}::uuid, email, invited_by, initial_role, ${JSON.stringify([...moved, ...groupEntries])}::jsonb, created_at, expires_at
        FROM kortix.account_invitations WHERE invite_id = ${invite.invite_id}
      RETURNING invite_id::text`);
    await tx.execute(sql`UPDATE kortix.account_invitations SET bootstrap_grants = ${JSON.stringify(kept)}::jsonb
      WHERE invite_id = ${invite.invite_id}`);
    if (created) out.invites.push({ inviteId: created.invite_id, sourceInviteId: invite.invite_id, moved });
  }
}

/**
 * Once the source holds one project it is a 1:1 workspace: its account takes
 * the keeper's name (invariant I6), the same rule as the M2 backfill, with the
 * old name kept in `workspace_name_backups` (the first backup wins).
 */
async function nameSourceAfterKeeper(tx: TransferTx, accountId: string): Promise<void> {
  const [keeper] = await tx.execute<{ name: string }>(sql`
    SELECT p.name FROM kortix.projects p WHERE p.account_id = ${accountId} AND p.status = 'active'
       AND (SELECT count(*) FROM kortix.projects q WHERE q.account_id = ${accountId} AND q.status = 'active') = 1`);
  if (!keeper) return;
  await tx.execute(sql`
    INSERT INTO kortix.workspace_name_backups (account_id, old_name, new_name)
    SELECT account_id, name, ${keeper.name} FROM kortix.accounts WHERE account_id = ${accountId} AND name IS DISTINCT FROM ${keeper.name}
    ON CONFLICT (account_id) DO NOTHING`);
  await tx.execute(sql`UPDATE kortix.accounts SET name = ${keeper.name}, updated_at = now()
    WHERE account_id = ${accountId} AND name IS DISTINCT FROM ${keeper.name}`);
}

/**
 * The inverse of `nameSourceAfterKeeper`: a source that holds 2+ projects
 * again after a reverse is a legacy account, so it gets back the name the
 * split replaced. Only when the name is still the one the split wrote; the
 * backup row goes, so a later split backs the name up again.
 */
async function restoreSourceName(tx: TransferTx, accountId: string): Promise<void> {
  await tx.execute(sql`
    WITH restored AS (
      DELETE FROM kortix.workspace_name_backups b
       USING kortix.accounts a
       WHERE b.account_id = ${accountId} AND a.account_id = b.account_id AND a.name = b.new_name
         AND (SELECT count(*) FROM kortix.projects p WHERE p.account_id = ${accountId} AND p.status = 'active') > 1
      RETURNING b.account_id, b.old_name)
    UPDATE kortix.accounts a SET name = restored.old_name, updated_at = now()
      FROM restored WHERE a.account_id = restored.account_id`);
}

/**
 * Split `projectId` out of `fromAccountId` into the new account `toAccountId`,
 * inside the caller's transaction. Refuses unless the source still holds 2+
 * active projects (`not_legacy`). The caller copied the project's site blobs
 * to the target prefix first (`copyProjectSiteBlobs`).
 */
export async function splitProjectIntoNewAccount(
  tx: TransferTx,
  input: { projectId: string; fromAccountId: string; toAccountId: string },
): Promise<SplitCopiedIds> {
  const { projectId, fromAccountId, toAccountId } = input;
  // Serialize splits of one account: the "still legacy" check below must see
  // the moves of a concurrent run.
  await tx.execute(sql`SELECT 1 FROM kortix.accounts WHERE account_id = ${fromAccountId} FOR UPDATE`);
  const [shape] = await tx.execute<{ here: boolean; active: number }>(sql`
    SELECT bool_or(project_id = ${projectId}) AS here, count(*)::int AS active
      FROM kortix.projects WHERE account_id = ${fromAccountId} AND status = 'active'`);
  if (!shape?.here) throw new ProjectSplitError('project_missing', 'Project is not an active project of the source account');
  if (shape.active < 2) throw new ProjectSplitError('not_legacy', 'The source account no longer holds several projects');

  const out: SplitCopiedIds = {
    account: toAccountId, memberships: [], groups: {}, roles: {}, accountAssignments: [], secrets: {},
    undecryptableSecrets: [], pools: [], githubInstallations: [], githubUserTokens: [], claudeLogins: [], invites: [],
  };
  const invites = await pendingInvitesForProject(tx, projectId, fromAccountId);
  await copyDirectory(tx, projectId, fromAccountId, toAccountId, invites.map((invite) => invite.email), out);
  await copyAccountSecrets(tx, projectId, fromAccountId, toAccountId, out);
  await copyIntegrations(tx, fromAccountId, toAccountId, out);
  await splitInvites(tx, projectId, fromAccountId, toAccountId, invites, out);
  const moved = await moveProjectInTransaction(tx, { projectId, fromAccountId, toAccountId }, { split: { groups: out.groups, roles: out.roles } });
  // Project-scoped secrets the source could not decrypt moved unchanged, marked for a reconnect.
  out.undecryptableSecrets.push(...moved.undecryptableSecrets);
  await nameSourceAfterKeeper(tx, fromAccountId);
  logger.info('[workspace-split] project split into its own account', {
    projectId, fromAccountId, toAccountId,
    memberships: out.memberships.length, groups: Object.keys(out.groups).length, roles: Object.keys(out.roles).length,
    secrets: Object.keys(out.secrets).length, invites: out.invites.length,
  });
  return out;
}

/**
 * Undo one split inside the caller's transaction: the project returns to
 * `fromAccountId` with its grants mapped back, the invites are rejoined, the
 * pools point at the source secrets again, and every row listed in `copied`
 * is deleted. The target account row stays as a dormant record with no
 * members. Refused when the target took money (a purchase, a Stripe customer,
 * a contract) or holds another project.
 *
 * A person added to the new workspace after the split who holds a grant on
 * the project gets a membership in the source, so the reverse never removes
 * access silently.
 */
export async function reverseProjectSplit(
  tx: TransferTx,
  input: { projectId: string; fromAccountId: string; toAccountId: string; copied: SplitCopiedIds },
): Promise<void> {
  const { projectId, fromAccountId, toAccountId, copied } = input;
  await tx.execute(sql`SELECT 1 FROM kortix.accounts WHERE account_id IN (${fromAccountId}, ${toAccountId}) ORDER BY account_id FOR UPDATE`);
  const [shape] = await tx.execute<{ here: boolean; active: number; money: boolean }>(sql`
    SELECT bool_or(project_id = ${projectId}) AS here, count(*)::int AS active,
      (EXISTS (SELECT 1 FROM kortix.credit_purchases WHERE account_id = ${toAccountId} AND status = 'completed')
        OR EXISTS (SELECT 1 FROM kortix.billing_customers WHERE account_id = ${toAccountId})
        OR EXISTS (SELECT 1 FROM kortix.enterprise_contracts WHERE account_id = ${toAccountId})) AS money
      FROM kortix.projects WHERE account_id = ${toAccountId} AND status = 'active'`);
  if (!shape?.here) throw new ProjectSplitError('reverse_refused', 'The project is no longer the active project of the split account');
  if (shape.active !== 1) throw new ProjectSplitError('reverse_refused', 'The split account holds another project');
  if (shape.money) throw new ProjectSplitError('reverse_refused', 'The split account has billing of its own');

  // Back to a legacy shape: flag both sides before the move so the 1:1 index
  // never sees two unflagged projects in the source.
  await tx.execute(sql`UPDATE kortix.projects SET split_pending = true
    WHERE status = 'active' AND (account_id = ${fromAccountId} OR project_id = ${projectId})
      AND EXISTS (SELECT 1 FROM kortix.projects WHERE account_id = ${fromAccountId} AND status = 'active')`);

  const groups = invert(copied.groups);
  const roles = invert(copied.roles);
  // Grants on directory objects made after the split have no source object.
  await tx.execute(sql`DELETE FROM kortix.role_assignments
    WHERE account_id = ${toAccountId} AND scope_type = 'project' AND scope_id = ${projectId}
      AND ((principal_type = 'group' AND NOT (${jsonMap(groups)}::jsonb ? principal_id::text))
        OR (role_id IN (SELECT role_id FROM kortix.roles WHERE account_id = ${toAccountId}) AND NOT (${jsonMap(roles)}::jsonb ? role_id::text)))`);
  await tx.execute(sql`
    INSERT INTO kortix.account_memberships (user_id, account_id)
    SELECT DISTINCT user_id, ${fromAccountId}::uuid FROM (
      SELECT principal_id AS user_id FROM kortix.role_assignments
       WHERE account_id = ${toAccountId} AND scope_type = 'project' AND scope_id = ${projectId} AND principal_type = 'user'
      UNION SELECT g.user_id FROM kortix.account_secret_grants g
        JOIN kortix.account_secret_resources r ON r.secret_id = g.secret_id
       WHERE r.account_id = ${toAccountId} AND r.project_id = ${projectId}) people
    ON CONFLICT (user_id, account_id) DO NOTHING`);

  await rewriteProjectPools(tx, projectId, invert(copied.secrets));
  for (const invite of copied.invites) {
    await tx.execute(sql`UPDATE kortix.account_invitations
      SET bootstrap_grants = COALESCE(bootstrap_grants, '[]'::jsonb) || ${JSON.stringify(invite.moved)}::jsonb
      WHERE invite_id = ${invite.sourceInviteId} AND accepted_at IS NULL`);
  }

  await moveProjectInTransaction(tx, { projectId, fromAccountId: toAccountId, toAccountId: fromAccountId }, { split: { groups, roles } });
  await restoreSourceName(tx, fromAccountId);

  const list = (values: string[]) => JSON.stringify(values);
  await tx.execute(sql`DELETE FROM kortix.account_invitations WHERE invite_id::text IN (SELECT jsonb_array_elements_text(${list(copied.invites.map((i) => i.inviteId))}::jsonb))`);
  await tx.execute(sql`DELETE FROM kortix.role_assignments WHERE assignment_id::text IN (SELECT jsonb_array_elements_text(${list(copied.accountAssignments)}::jsonb))`);
  await tx.execute(sql`DELETE FROM kortix.account_secret_resources WHERE account_id = ${toAccountId} AND secret_id::text IN (SELECT jsonb_array_elements_text(${list(Object.values(copied.secrets))}::jsonb))`);
  await tx.execute(sql`DELETE FROM kortix.account_github_installations WHERE account_id = ${toAccountId} AND installation_row_id::text IN (SELECT jsonb_array_elements_text(${list(copied.githubInstallations)}::jsonb))`);
  await tx.execute(sql`DELETE FROM kortix.account_github_user_tokens WHERE account_id = ${toAccountId} AND token_row_id::text IN (SELECT jsonb_array_elements_text(${list(copied.githubUserTokens)}::jsonb))`);
  await tx.execute(sql`DELETE FROM kortix.claude_subscription_logins WHERE account_id = ${toAccountId} AND user_id::text IN (SELECT jsonb_array_elements_text(${list(copied.claudeLogins)}::jsonb))`);
  await tx.execute(sql`DELETE FROM kortix.roles WHERE account_id = ${toAccountId} AND role_id::text IN (SELECT jsonb_array_elements_text(${list(Object.values(copied.roles))}::jsonb))`);
  await tx.execute(sql`DELETE FROM kortix.account_groups WHERE account_id = ${toAccountId} AND group_id::text IN (SELECT jsonb_array_elements_text(${list(Object.values(copied.groups))}::jsonb))`);
  await tx.execute(sql`DELETE FROM kortix.account_memberships WHERE account_id = ${toAccountId} AND user_id::text IN (SELECT jsonb_array_elements_text(${list(copied.memberships)}::jsonb))`);
  logger.info('[workspace-split] split reversed', { projectId, fromAccountId, toAccountId });
}
